183	  @override
184	  Future<String> get sdkNameAndVersion async => _sdkNameAndVersion ??= await _computeSdkNameAndVersion();
185	
186	  String _sdkNameAndVersion;
187	  Future<String> _computeSdkNameAndVersion() async {
188	    if (!isSupported()) {
189	      return 'unknown';
190	    }
191	    // See https://bugs.chromium.org/p/chromium/issues/detail?id=158372
192	    String version = 'unknown';
193	    if (_platform.isWindows) {
194	      final ProcessResult result = await _processManager.run(<String>[
195	        r'reg', 'query', r'HKEY_CURRENT_USER\Software\Google\Chrome\BLBeacon', '/v', 'version',
196	      ]);
197	      if (result.exitCode == 0) {
198	        final List<String> parts = (result.stdout as String).split(RegExp(r'\s+'));
199	        if (parts.length > 2) {
200	          version = 'Google Chrome ' + parts[parts.length - 2];
201	        }
202	      }
203	    } else {
204	      final String chrome = chromeLauncher.findExecutable();
205	      final ProcessResult result = await _processManager.run(<String>[
206	        chrome,
207	        '--version',
208	      ]);
209	      if (result.exitCode == 0) {
210	        version = result.stdout as String;
211	      }
212	    }
213	    return version.trim();
214	  }
215	
