26	/// The expected executable name on linux.
27	const String kLinuxExecutable = 'google-chrome';
28	
29	/// The expected executable name on macOS.
30	const String kMacOSExecutable =
31	    '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
32	
33	/// The expected Chrome executable name on Windows.
34	const String kWindowsExecutable = r'Google\Chrome\Application\chrome.exe';
35	
